//! Lineage 2 terrain importer and clean map inspector.
use bevy::prelude::*;
use mashup::{MashupPlugin,game::lineage2::{importers::{self,ImportOptions},world_viewer::{self,Lineage2WorldViewerPlugin,ViewerOptions}},maps::{MapPackage,collision::MeshCollisionWorld,runtime::{MapRuntime,StreamingFocus}}};
use std::path::PathBuf;

fn run()->Result<(),String>{let args:Vec<_>=std::env::args().skip(1).collect();let mut import=false;let mut options=ImportOptions::default();let mut package=PathBuf::from(importers::DEFAULT_DESTINATION).join("world.mashup.json");let mut radius: f32=500.0;let mut capture=None;let mut index=0;
    while index<args.len(){let arg=&args[index];let mut value=||{index+=1;args.get(index).cloned().ok_or_else(||format!("{arg} requires a value"))};match arg.as_str(){
        "--import"=>import=true,"--extracted"=>options.extracted=value()?.into(),"--destination"=>options.destination=value()?.into(),"--tile"=>options.tile=value()?,"--tile-size-source"=>options.tile_size_source=value()?.parse().map_err(|_|"invalid source tile size")?,"--meters-per-source-unit"=>options.meters_per_source_unit=value()?.parse().map_err(|_|"invalid source unit scale")?,"--height-scale"=>options.meters_per_height_sample=value()?.parse().map_err(|_|"invalid height sample scale")?,"--map"=>package=value()?.into(),"--stream-radius"=>radius=value()?.parse().map_err(|_|"invalid stream radius")?,"--capture-after"=>capture=Some(value()?.parse().map_err(|_|"invalid capture delay")?),
        "--help"|"-h"=>{println!("mashup-lineage2 --import [--extracted PATH] [--destination PATH] [--tile 22_22] [--tile-size-source UU] [--meters-per-source-unit M] [--height-scale M]\nmashup-lineage2 [--map assets/imported/lineage2/main/world.mashup.json] [--stream-radius METERS] [--capture-after SECONDS]\nImports one extracted 256x256 G16 terrain tile into the shared package and opens the Lineage 2 terrain inspector. See docs/lineage2.md for extraction and fidelity details.");return Ok(())},_=>return Err(format!("unknown argument {arg}"))}index+=1;}
    if !radius.is_finite()||radius<=0.0||capture.is_some_and(|s:f32|!s.is_finite()||s<0.0){return Err("stream radius must be positive and capture delay nonnegative".into());}if import{importers::import(&options)?;return Ok(())}
    let path=std::path::absolute(&package).map_err(|e|e.to_string())?;let package=MapPackage::open(&path)?;let collision=MeshCollisionWorld::new(package.manifest["chunks"].as_array().unwrap())?;let spawn=world_viewer::spawn(&package)?;let assets=std::path::absolute("assets").map_err(|e|e.to_string())?;let prefix=package.root.strip_prefix(&assets).map_err(|_|"world package must be under assets/")?.to_string_lossy().replace('\\',"/");
    App::new().add_plugins(DefaultPlugins.set(AssetPlugin{file_path:assets.to_string_lossy().into_owned(),..default()}).set(WindowPlugin{primary_window:Some(Window{title:"Mashup — Lineage 2 terrain".into(),resolution:(1280,720).into(),focused:false,..default()}),..default()})).add_plugins(MashupPlugin).insert_resource(package).insert_resource(collision).insert_resource(MapRuntime::new(prefix)).insert_resource(StreamingFocus{position:spawn,radius}).insert_resource(ViewerOptions{output:"user_data/mashup-lineage2".into(),capture_after:capture}).add_plugins(Lineage2WorldViewerPlugin).run();Ok(())}
fn main(){if let Err(error)=run(){eprintln!("Cannot start Lineage 2: {error}");std::process::exit(1);}}
